import re

ACT = re.compile(r'^(?P<action>Inst|Conf|Remv|Purg)\s+(?P<package>\S+)(?:\s+\[(?P<old>[^\]]*)\])?(?:\s+\((?P<version>\S+)\s+(?P<archives>.*?)(?:\s+\[(?P<arch>[^\]]+)\])?\))?\s*$')
SUM = re.compile(r'^(?P<upgraded>\d+) upgraded, (?P<new>\d+) newly installed, (?P<remove>\d+) to remove and (?P<held>\d+) not upgraded\.?\s*$')
PROG = re.compile(r'^(Reading |Building |Calculating |Done|NOTE:|WARNING:)')

def parse(lines):
    skip = []
    lists = {'name': 'package_lists', 'kind': 'table', 'lines': [], 'records': []}
    acts = {'name': 'actions', 'kind': 'table', 'lines': [], 'records': []}
    summ = {'name': 'summary', 'kind': 'kv', 'lines': [], 'records': []}
    section = None
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        m = ACT.match(ln)
        if m:
            section = None
            acts['lines'].append(i)
            acts['records'].append({'action': m.group('action'), 'package': m.group('package'), 'old_version': m.group('old') or '', 'version': m.group('version') or '', 'archives': m.group('archives') or '', 'arch': m.group('arch') or ''})
            continue
        m = SUM.match(ln)
        if m:
            section = None
            summ['lines'].append(i)
            summ['records'].append({'upgraded': int(m.group('upgraded')), 'newly installed': int(m.group('new')), 'to remove': int(m.group('remove')), 'not upgraded': int(m.group('held'))})
            continue
        if ln[:1] in (' ', '\t') and section is not None:
            lists['lines'].append(i)
            for p in ln.split():
                lists['records'].append({'section': section, 'package': p})
            continue
        if ln.rstrip().endswith(':') and not ln.startswith(' '):
            section = ln.strip()[:-1]
            lists['lines'].append(i)
            continue
        if PROG.match(ln):
            skip.append(i)
            continue
    blocks = [b for b in (lists, summ, acts) if b['lines']]
    return {'blocks': blocks, 'skip': skip}
